package com.bm4a.platform.modules.files.internal;

import java.io.InputStream;
import java.nio.file.Path;

/**
 * Object store port. Keys are generated by the files module ({@code <orgId>/<yyyy>/<mm>/<uuid>}); adapters never see
 * client input. Failures of the backing store surface as 503 {@code file_storage_unavailable}.
 */
interface FileStorage {

    /** Stores the content of {@code source}; an existing object under {@code key} is replaced. */
    void put(String key, Path source, long sizeBytes, String contentType);

    /** The object content; 404 when the object does not exist. The caller closes the stream. */
    InputStream open(String key);

    /** Removes the object if it exists. */
    void delete(String key);
}
